[<Interface>]
type MediaEvictionConfig =
    /// <summary>
    /// Messages at the tail of the active path that are never evicted.
    /// Think clamps this to at least the read-time window the model replays at
    /// full fidelity, so a misconfigured low value can never strip content the
    /// model still sees.
    /// </summary>
    /// <defaultValue>8</defaultValue>
    abstract keepRecentMessages: float option with get, set
    /// <summary>
    /// Minimum decoded payload size, in bytes, for a value to be evicted.
    /// </summary>
    /// <defaultValue>32 * 1024</defaultValue>
    abstract minPartBytes: float option with get, set
    /// <summary>
    /// Maximum stored rows processed per pass. Bounds how long a single pass
    /// can take; remaining rows are picked up by the next pass.
    /// </summary>
    /// <defaultValue>64</defaultValue>
    abstract maxRowsPerPass: float option with get, set
    /// <remarks>
    /// @deprecated
    /// Ignored. Evicted bytes are always preserved in the Workspace
    /// under <c>/workspace/attachments/evicted/</c>; there is no drop-the-bytes mode. Accepted
    /// so existing configurations keep compiling.
    /// </remarks>
    abstract externalizeToWorkspace: bool option with get, set
    [<ParamObject; Emit("$0")>]
    static member Create (?keepRecentMessages: float, ?minPartBytes: float, ?maxRowsPerPass: float, ?externalizeToWorkspace: bool) : MediaEvictionConfig = jsNative

