/// <summary>
/// Options for Think.addMessages.
/// </summary>
[<Interface>]
type AddMessagesOptions =
    /// <summary>
    /// Parent to attach the first message under. Omitted (<c>undefined</c>) attaches to
    /// the latest committed leaf at call time; <c>null</c> attaches at the root. An
    /// explicit id that does not exist throws (fail fast rather than silently
    /// misattaching). Subsequent messages in an array chain under the previous one.
    /// </summary>
    abstract parentId: string option with get, set
    /// <summary>
    /// <c>"append"</c> (default) inserts new rows, idempotent by message id.
    /// <c>"upsert"</c> inserts, or updates in place when the id already exists (in which
    /// case <c>parentId</c> is ignored — re-parenting is not supported).
    /// <br /><br />
    /// Idempotency is by id against the whole session tree, not just the target
    /// path: if a message id already exists <i>anywhere</i> in history, <c>"append"</c> is a
    /// no-op for it (no new row, no re-parent) and <c>"upsert"</c> updates it in place
    /// wherever it lives. In both modes the next message in the array chains under
    /// that existing id, so passing already-present ids mid-array threads new
    /// messages onto the existing branch rather than forking a new one.
    /// </summary>
    abstract mode: AddMessagesOptions.Mode option with get, set
    /// <summary>
    /// Broadcast the change to connected clients. Default <c>true</c>. Has no effect
    /// when called from inside an active turn (e.g. a tool <c>execute</c>), where the
    /// live view is intentionally not touched until the next turn's sync.
    /// </summary>
    abstract broadcast: bool option with get, set
    [<ParamObject; Emit("$0")>]
    static member Create (?parentId: string, ?mode: AddMessagesOptions.Mode, ?broadcast: bool) : AddMessagesOptions = jsNative

