/// <summary>
/// Opt-in handling for a turn that overflows the model's context window
/// mid-flight. Compaction (<c>compactAfter()</c>) is only checked between turns, so a
/// long, tool-heavy turn can grow past the window before the next check; the
/// provider then rejects the request (<c>"prompt is too long"</c> /
/// <c>context_length_exceeded</c>). Both layers reuse the session's compaction
/// function and are provider-agnostic — the app maps the error via
/// Think.classifyChatError; Think never matches provider strings itself.
/// <br /><br />
/// Set <c>Think.contextOverflow</c> to enable. Leaving it unset disables both layers
/// (existing terminal behavior).
/// </summary>
[<Interface>]
type ContextOverflowConfig =
    /// <summary>
    /// Reactive backstop. When a turn fails with an error classified as
    /// <c>"context_overflow"</c>, discard the truncated partial, run
    /// <c>session.compact()</c>, and re-run the turn from the compacted history. The
    /// partial is intentionally not persisted: the turn restarts from scratch, so
    /// keeping the cut-off assistant message would orphan it beside the recovered
    /// answer (and duplicate any tool work the retry re-issues). If compaction
    /// cannot shorten history or the retry budget is spent, the overflow surfaces
    /// terminally through <c>onChatError</c> (classified) — it never loops or ends
    /// silently. Default <c>false</c>.
    /// </summary>
    abstract reactive: bool option with get, set
    /// <summary>
    /// Maximum compact-and-retry attempts for a single overflowing turn (the
    /// reactive backstop). Independent of the proactive guard's cap — see
    /// proactive.maxCompactions. Default <c>1</c>.
    /// </summary>
    abstract maxRetries: float option with get, set
    /// <summary>
    /// Proactive guard. Before each step, read the previous step's model-reported
    /// <c>usage.inputTokens</c> and, if it crosses <c>maxInputTokens * (headroom ?? 0.9)</c>,
    /// compact in place and feed the recompacted history into the upcoming step —
    /// heading off the provider rejection before it happens. Keys off usage (every
    /// provider reports it), not provider error strings. Unset disables it.
    /// <br /><br />
    /// If a provider omits <c>inputTokens</c>, the guard falls back to <c>usage.totalTokens</c>
    /// (input + output) — a safe over-approximation that compacts slightly early
    /// rather than missing the threshold. If neither is reported, the guard does
    /// nothing that step (the reactive backstop still catches a genuine overflow).
    /// <br /><br />
    /// <c>maxCompactions</c> caps how many times the guard may compact within a single
    /// step loop (default <c>1</c>, floored at <c>1</c>). It is independent of
    /// maxRetries (the reactive budget): a no-op compaction would repeat on
    /// every step, so the cap stops the guard from compacting (and emitting
    /// <c>chat:context:compacted</c>) on each one.
    /// </summary>
    abstract proactive: ContextOverflowConfig.Proactive option with get, set
    [<ParamObject; Emit("$0")>]
    static member Create (?reactive: bool, ?maxRetries: float, ?proactive: ContextOverflowConfig.Proactive) : ContextOverflowConfig = jsNative

