    /// beforeToolCall(ctx: ToolCallContext): ToolCallDecision | void {
    /// if (ctx.toolName === "delete" &amp;&amp; this.isReadOnlyMode) {
    /// return { action: "block", reason: "delete is disabled in read-only mode" };
    /// }
