    abstract deleteSubmission: submissionId: string -> JS.Promise<bool>
    abstract deleteSubmissions: ?options: DeleteSubmissionsOptions -> JS.Promise<float>
    abstract cancelSubmission: submissionId: string * ?reason: obj -> JS.Promise<CancelSubmissionResult>
