    /// <summary>
    /// Inject messages and trigger a model turn — without a WebSocket request.
    /// <br /><br />
    /// Use for scheduled responses, webhook-triggered turns, proactive agents,
    /// or chaining from <c>onChatResponse</c>.
    /// <br /><br />
    /// Accepts static messages or a callback that derives messages from the
    /// current state (useful when multiple calls queue up — the callback runs
    /// with the latest messages when the turn actually starts).
    /// <br /><br />
    /// Pass <c>options.signal</c> to cancel the turn from outside without knowing
    /// the internally-generated request id. The signal is linked to the
    /// registry's controller for this turn — when it aborts, the inference
    /// loop's signal aborts and the result reports <c>status: "aborted"</c>.
    /// Pre-aborted signals short-circuit before any model work runs. See
    /// SaveMessagesOptions for the integration point.
    /// </summary>
    /// <example>
    /// <code>
    /// Scheduled follow-up
    /// ```typescript
    /// async onScheduled() {
    /// await this.saveMessages([{
    /// id: crypto.randomUUID(),
    /// role: "user",
    /// parts: [{ type: "text", text: "Time for your daily summary." }]
    /// }]);
    /// }
    /// </code>
    /// <code>
    /// </code>
    /// </example>
    /// <example>
    /// <code>
    /// Function form
    /// ```typescript
    /// await this.saveMessages((current) =&gt; [
    /// ...current,
    /// { id: crypto.randomUUID(), role: "user", parts: [{ type: "text", text: "Continue." }] }
    /// ]);
    /// </code>
    /// <code>
    /// </code>
    /// </example>
    /// <example>
    /// <code>
    /// External cancellation (helper-as-sub-agent)
    /// ```typescript
    /// // Inside a parent agent's tool execute — forward the AI SDK's
    /// // abortSignal so a parent stop / tab close cancels the helper.
    /// await helper.saveMessages([userMsg], { signal: abortSignal });
    /// </code>
    /// <code>
    /// </code>
    /// </example>
    abstract saveMessages: messages: U2<FSharp.CloudEdge.Support.AI.V7.UIMessage<obj, JS.Record<string, obj>, JS.Record<string, FSharp.CloudEdge.Support.AI.V7.UITool>>[], (FSharp.CloudEdge.Support.AI.V7.UIMessage<obj, JS.Record<string, obj>, JS.Record<string, FSharp.CloudEdge.Support.AI.V7.UITool>>[] -> U2<FSharp.CloudEdge.Support.AI.V7.UIMessage<obj, JS.Record<string, obj>, JS.Record<string, FSharp.CloudEdge.Support.AI.V7.UITool>>[], JS.Promise<FSharp.CloudEdge.Support.AI.V7.UIMessage<obj, JS.Record<string, obj>, JS.Record<string, FSharp.CloudEdge.Support.AI.V7.UITool>>[]>>)> * ?options: FSharp.CloudEdge.Runtime.Agents.Chat.SaveMessagesOptions -> JS.Promise<FSharp.CloudEdge.Runtime.Agents.Chat.SaveMessagesResult>
    /// <summary>
    /// Add messages to history WITHOUT starting a model turn.
    /// <br /><br />
    /// Distinct from Think.saveMessages (which runs a turn) and from
    /// AIChatAgent's <c>persistMessages()</c> (which replaces/reconciles a flat array):
    /// <c>addMessages</c> appends or upserts into the Session tree and never enqueues a
    /// turn. Because it bypasses the turn queue, it never deadlocks — including
    /// when called from inside a tool <c>execute</c> during an active turn.
    /// <br /><br />
    /// Array entries are appended <b>linearly</b>: the first attaches under the
    /// resolved parent (the latest committed leaf by default, or <c>parentId</c>), and
    /// each subsequent message attaches under the previous one, so imported history
    /// stays a single path rather than a fan-out of siblings. Appends are
    /// idempotent by message id; pass <c>{ mode: "upsert" }</c> to update an existing
    /// message in place instead (upsert never re-parents). Any role may be written;
    /// an <c>assistant</c> message added this way is inert transcript data (it does not
    /// mark a completed turn or trigger auto-continuation).
    /// <br /><br />
    /// The live message cache stays coherent automatically (the Session keeps it
    /// in sync on every write, branches included). Broadcast behaviour depends on
    /// whether a turn is running:
    /// <br /><br />
    /// - <b>Out of a turn</b> (the supported pattern — "add context, then run a
    ///   turn"): the new messages are broadcast to connected clients immediately
    ///   (unless <c>broadcast: false</c>).
    /// - <b>Inside a turn</b> (e.g. from a tool <c>execute</c>): no broadcast is sent, so a
    ///   full snapshot can't clobber the in-progress streamed message; the injected
    ///   messages ride along on the turn's next broadcast. The write is still
    ///   durable and visible to the running turn's next sync.
    /// </summary>
    abstract addMessages: messages: U2<FSharp.CloudEdge.Support.AI.V7.UIMessage<obj, JS.Record<string, obj>, JS.Record<string, FSharp.CloudEdge.Support.AI.V7.UITool>>[], (FSharp.CloudEdge.Support.AI.V7.UIMessage<obj, JS.Record<string, obj>, JS.Record<string, FSharp.CloudEdge.Support.AI.V7.UITool>>[] -> U2<FSharp.CloudEdge.Support.AI.V7.UIMessage<obj, JS.Record<string, obj>, JS.Record<string, FSharp.CloudEdge.Support.AI.V7.UITool>>[], JS.Promise<FSharp.CloudEdge.Support.AI.V7.UIMessage<obj, JS.Record<string, obj>, JS.Record<string, FSharp.CloudEdge.Support.AI.V7.UITool>>[]>>)> * ?options: AddMessagesOptions -> JS.Promise<unit>
    /// <summary>
    /// Run a new LLM call following the last assistant message.
    /// <br /><br />
    /// The model sees the full conversation (including the last assistant
    /// response) and generates a new response. The new response is persisted
    /// as a separate assistant message. Building block for chat recovery
    /// (Phase 4), "generate more" buttons, and self-correction.
    /// <br /><br />
    /// Note: this creates a new message, not an append to the existing one.
    /// Recovery continuations (<c>trigger: "recovery-continue"</c>) are the exception:
    /// they stream into the interrupted assistant message so it stays one message.
    /// <br /><br />
    /// Returns early with <c>status: "skipped"</c> if there is no assistant message
    /// to continue from.
    /// <br /><br />
    /// Pass <c>options.signal</c> to cancel the continuation from outside —
    /// matches the saveMessages contract.
    /// </summary>
